-- INAVIT_DW: definiciones de vistas (extraidas de _V_VIEW, 2026-11-18)
-- Texto normalizado por el catalogo de Netezza. Ejecutar DESPUES de crear las tablas.
-- Orden: V_PRECALIFICADOS antes de V_PRECALIFICADOS_DASH (dependencia).

-- ===== V_FACT_APORTACION =====
CREATE OR REPLACE VIEW INAVIT_DW.V_FACT_APORTACION AS
SELECT A.APORTACION_ID, A.NSS, A.REGISTRO_PATRONAL, PA.RAZON_SOCIAL AS PATRON, PA.SECTOR, PA.TAMANIO, PA.ESTATUS AS ESTATUS_PATRON, PA.ES_OMISO AS PATRON_OMISO, PA.ENTIDAD_CLAVE, E.NOMBRE AS ENTIDAD, E.REGION, A.PERIODO, D.ANIO, D.BIMESTRE, D.FECHA_LIMITE_PAGO, A.SDI, A.DIAS_COTIZADOS, A.MONTO_APORTACION, A.FECHA_PAGO, (A.FECHA_PAGO - D.FECHA_LIMITE_PAGO) AS DIAS_DESPUES_LIMITE, A.ORIGEN, A.DQ_DIAS_INVALIDOS, A.DQ_MONTO_CERO FROM (((INAVIT_DW.FACT_APORTACION A JOIN INAVIT_DW.DIM_PERIODO D ON ((D.PERIODO = A.PERIODO))) LEFT JOIN INAVIT_DW.DIM_PATRON PA ON ((PA.REGISTRO_PATRONAL = A.REGISTRO_PATRONAL))) LEFT JOIN INAVIT_DW.DIM_ENTIDAD E ON ((E.CLAVE = PA.ENTIDAD_CLAVE)));

-- ===== V_FACT_CREDITO =====
CREATE OR REPLACE VIEW INAVIT_DW.V_FACT_CREDITO AS
SELECT C.NUM_CREDITO, C.NSS, C.CURP, C.RFC, C.NOMBRE_ACREDITADO, C.PRODUCTO_ID, P.NOMBRE AS PRODUCTO, P.TIPO AS TIPO_PRODUCTO, C.ENTIDAD_CLAVE, E.NOMBRE AS ENTIDAD, E.REGION, C.MUNICIPIO, C.REGISTRO_PATRONAL, PA.RAZON_SOCIAL AS PATRON, PA.ES_OMISO AS PATRON_OMISO, C.FECHA_ORIGINACION, C.MONTO_ORIGINAL, C.PLAZO_MESES, C.TASA_ANUAL, C.MENSUALIDAD, C.SALDO_ACTUAL, C.ESTATUS_CREDITO, C.DIAS_MORA, C.FECHA_ULTIMO_PAGO, CASE WHEN ((C.ESTATUS_CREDITO = 'MOROSO'::"VARCHAR") OR (C.ESTATUS_CREDITO = 'CARTERA_VENCIDA'::"VARCHAR")) THEN 1 ELSE 0 END AS ES_MOROSO, CASE WHEN (C.DIAS_MORA = 0) THEN '0 - Al corriente'::"VARCHAR" WHEN (C.DIAS_MORA <= 30) THEN '1 - 1 a 30 dias'::"VARCHAR" WHEN (C.DIAS_MORA <= 90) THEN '2 - 31 a 90 dias'::"VARCHAR" WHEN (C.DIAS_MORA <= 180) THEN '3 - 91 a 180 dias'::"VARCHAR" ELSE '4 - Mas de 180 dias'::"VARCHAR" END AS RANGO_MORA, C.SEXO, C.FECHA_NACIMIENTO, C.SDI, C.ESTATUS_TRABAJADOR, C.DQ_NSS_CORREGIDO, C.DQ_CURP_CORREGIDA, C.DQ_ESTATUS_CORREGIDO, C.DQ_NOMBRE_CORREGIDO, C.DQ_NOMBRE_DISCREPANTE, C.DQ_FECHA_NAC_INVALIDA FROM (((INAVIT_DW.CREDITO_INTEGRADO C LEFT JOIN INAVIT_DW.DIM_PRODUCTO P ON ((P.PRODUCTO_ID = C.PRODUCTO_ID))) LEFT JOIN INAVIT_DW.DIM_ENTIDAD E ON ((E.CLAVE = C.ENTIDAD_CLAVE))) LEFT JOIN INAVIT_DW.DIM_PATRON PA ON ((PA.REGISTRO_PATRONAL = C.REGISTRO_PATRONAL)));

-- ===== V_FACT_PAGO =====
CREATE OR REPLACE VIEW INAVIT_DW.V_FACT_PAGO AS
SELECT P.PAGO_ID, P.NUM_CREDITO, C.NSS, C.PRODUCTO_ID, C.ENTIDAD_CLAVE, P.FECHA_PAGO, P.PERIODO AS PERIODO_MES, ((SUBSTR(P.PERIODO, 1, 4) || '0'::"VARCHAR") || ("VARCHAR"(((INT4(SUBSTR(P.PERIODO, 5, 2)) + 1) / 2)))::VARCHAR(1)) AS PERIODO_BIMESTRE, P.MONTO_PAGO, P.TIPO_PAGO, P.CANAL FROM (INAVIT_DW.FACT_PAGO P JOIN INAVIT_DW.CREDITO_INTEGRADO C ON ((C.NUM_CREDITO = P.NUM_CREDITO)));

-- ===== V_PATRON_OMISO =====
CREATE OR REPLACE VIEW INAVIT_DW.V_PATRON_OMISO AS
SELECT P.REGISTRO_PATRONAL, P.RAZON_SOCIAL, P.SECTOR, P.TAMANIO, P.ENTIDAD_CLAVE, E.NOMBRE AS ENTIDAD, E.REGION, P.ESTATUS, P.ULTIMO_PERIODO_APORTACION, CASE WHEN (P.ESTATUS = 'A'::"VARCHAR") THEN 1 ELSE 0 END AS OMISO_OCULTO, CASE WHEN (T.TRABAJADORES NOTNULL) THEN T.TRABAJADORES WHEN (0 NOTNULL) THEN '0'::INT8 ELSE NULL::INT8 END AS TRABAJADORES_AFECTADOS, CASE WHEN (C.CREDITOS NOTNULL) THEN C.CREDITOS WHEN (0 NOTNULL) THEN '0'::INT8 ELSE NULL::INT8 END AS CREDITOS_EN_RIESGO, CASE WHEN (C.SALDO NOTNULL) THEN C.SALDO WHEN (0 NOTNULL) THEN '0'::NUMERIC ELSE NULL::"NUMERIC" END AS SALDO_EN_RIESGO, CASE WHEN (C.MOROSOS NOTNULL) THEN C.MOROSOS WHEN (0 NOTNULL) THEN '0'::NUMERIC ELSE NULL::"NUMERIC" END AS CREDITOS_MOROSOS FROM (((INAVIT_DW.DIM_PATRON P LEFT JOIN INAVIT_DW.DIM_ENTIDAD E ON ((E.CLAVE = P.ENTIDAD_CLAVE))) LEFT JOIN (SELECT INAVIT_DW.DIM_TRABAJADOR.REGISTRO_PATRONAL, COUNT(*) AS TRABAJADORES FROM INAVIT_DW.DIM_TRABAJADOR WHERE (INAVIT_DW.DIM_TRABAJADOR.ES_DUPLICADO_CURP = 0) GROUP BY INAVIT_DW.DIM_TRABAJADOR.REGISTRO_PATRONAL) T ON ((T.REGISTRO_PATRONAL = P.REGISTRO_PATRONAL))) LEFT JOIN (SELECT INAVIT_DW.CREDITO_INTEGRADO.REGISTRO_PATRONAL, COUNT(*) AS CREDITOS, SUM(INAVIT_DW.CREDITO_INTEGRADO.SALDO_ACTUAL) AS SALDO, SUM(CASE WHEN ((INAVIT_DW.CREDITO_INTEGRADO.ESTATUS_CREDITO = 'MOROSO'::"VARCHAR") OR (INAVIT_DW.CREDITO_INTEGRADO.ESTATUS_CREDITO = 'CARTERA_VENCIDA'::"VARCHAR")) THEN 1 ELSE 0 END) AS MOROSOS FROM INAVIT_DW.CREDITO_INTEGRADO GROUP BY INAVIT_DW.CREDITO_INTEGRADO.REGISTRO_PATRONAL) C ON ((C.REGISTRO_PATRONAL = P.REGISTRO_PATRONAL))) WHERE (P.ES_OMISO = 1);

-- ===== V_PRECALIFICADOS =====
CREATE OR REPLACE VIEW INAVIT_DW.V_PRECALIFICADOS AS
SELECT T.NSS, T.CURP, T.NOMBRE, T.APELLIDO_PATERNO, T.APELLIDO_MATERNO, T.ENTIDAD_CLAVE, E.NOMBRE AS ENTIDAD, E.REGION, T.REGISTRO_PATRONAL, T.SDI, S.SALDO_PESOS, S.BIMESTRES_COTIZADOS, S.FECHA_ULTIMA_APORTACION, CASE WHEN (S.SALDO_PESOS < '200000'::NUMERIC(6,0)) THEN '1 - 150 a 200 mil'::"VARCHAR" WHEN (S.SALDO_PESOS < '300000'::NUMERIC(6,0)) THEN '2 - 200 a 300 mil'::"VARCHAR" WHEN (S.SALDO_PESOS < '400000'::NUMERIC(6,0)) THEN '3 - 300 a 400 mil'::"VARCHAR" ELSE '4 - Más de 400 mil'::"NVARCHAR" END AS RANGO_SALDO, CASE WHEN (S.BIMESTRES_COTIZADOS < 48) THEN '1 - 24 a 47'::"VARCHAR" WHEN (S.BIMESTRES_COTIZADOS < 72) THEN '2 - 48 a 71'::"VARCHAR" ELSE '3 - 72 o más'::"NVARCHAR" END AS RANGO_ANTIGUEDAD, CASE WHEN (P.ES_OMISO NOTNULL) THEN INT4(P.ES_OMISO) WHEN (0 NOTNULL) THEN 0 ELSE NULL::INT4 END AS PATRON_OMISO FROM ((((INAVIT_DW.DIM_TRABAJADOR T JOIN INAVIT_DW.FACT_SUBCUENTA S ON ((S.NSS = T.NSS))) LEFT JOIN INAVIT_DW.DIM_ENTIDAD E ON ((E.CLAVE = T.ENTIDAD_CLAVE))) LEFT JOIN INAVIT_DW.DIM_PATRON P ON ((P.REGISTRO_PATRONAL = T.REGISTRO_PATRONAL))) LEFT JOIN INAVIT_DW.CREDITO_INTEGRADO C ON ((C.NSS = T.NSS))) WHERE (((((C.NSS ISNULL) AND (T.ESTATUS = 'A'::"VARCHAR")) AND (T.ES_DUPLICADO_CURP = 0)) AND (S.BIMESTRES_COTIZADOS >= 24)) AND (S.SALDO_PESOS >= '150000'::NUMERIC(6,0)));

-- ===== V_PRECALIFICADOS_DASH =====
CREATE OR REPLACE VIEW INAVIT_DW.V_PRECALIFICADOS_DASH AS
SELECT INAVIT_DW.V_PRECALIFICADOS.NSS, INAVIT_DW.V_PRECALIFICADOS.CURP, INAVIT_DW.V_PRECALIFICADOS.NOMBRE, INAVIT_DW.V_PRECALIFICADOS.APELLIDO_PATERNO, INAVIT_DW.V_PRECALIFICADOS.APELLIDO_MATERNO, INAVIT_DW.V_PRECALIFICADOS.ENTIDAD_CLAVE, INAVIT_DW.V_PRECALIFICADOS.ENTIDAD, INAVIT_DW.V_PRECALIFICADOS.REGION, INAVIT_DW.V_PRECALIFICADOS.REGISTRO_PATRONAL, INAVIT_DW.V_PRECALIFICADOS.SDI, INAVIT_DW.V_PRECALIFICADOS.SALDO_PESOS, INAVIT_DW.V_PRECALIFICADOS.BIMESTRES_COTIZADOS, INAVIT_DW.V_PRECALIFICADOS.FECHA_ULTIMA_APORTACION, INAVIT_DW.V_PRECALIFICADOS.RANGO_SALDO, INAVIT_DW.V_PRECALIFICADOS.RANGO_ANTIGUEDAD, INAVIT_DW.V_PRECALIFICADOS.PATRON_OMISO FROM INAVIT_DW.V_PRECALIFICADOS;
